     5	// TwoSumBrute is a brute force implementation.
     6	// O(N^2) time where N is the size of numbers.
     7	// O(1) space
     8	func TwoSumBrute(numbers []int, k int) bool {
     9		for i, x := range numbers {
    10			for j, y := range numbers {
    11				if i != j && x+y == k {
    12					return true
    13				}
    14			}
    15		}
    16		return false
    17	}
    18	
    19	// TwoSumBetter is asymptotically better than brute force
    20	// O(N log N) time because sorting.
    21	// O(N) space to prevent modifying the original number slice.
    22	func TwoSumBetter(numbers []int, k int) bool {
    23		copied := append([]int(nil), numbers...)
    24		sort.Ints(copied)
    25		for i, x := range copied {
    26			j := sort.SearchInts(copied, k-x)
    27			if i != j && j != len(copied) && copied[j] == k-x {
    28				return true
    29			}
    30		}
    31		return false
    32	}
    33	
    34	// TwoSumBest requires only a single pass in the worst case.
    35	// O(N) time
    36	// O(N) space
    37	func TwoSumBest(numbers []int, k int) bool {
    38		seen := make(map[int]struct{})
    39		for _, v := range numbers {
    40			if _, found := seen[k-v]; found {
    41				return true
    42			}
    43			seen[v] = struct{}{}
    44		}
    45		return false
    46	}
