    17	}
    18	
    19	// TwoSumBetter is asymptotically better than brute force
    20	// O(N log N) time because sorting.
    21	// O(N) space to prevent modifying the original number slice.
    22	func TwoSumBetter(numbers []int, k int) bool {
    23		copied := append([]int(nil), numbers...)
    24		sort.Ints(copied)
    25		for i, x := range copied {
    26			j := sort.SearchInts(copied, k-x)
    27			if i != j && j != len(copied) && copied[j] == k-x {
    28				return true
    29			}
    30		}
    31		return false
    32	}
