    35	// O(N) time
    36	// O(N) space
    37	func TwoSumBest(numbers []int, k int) bool {
    38		seen := make(map[int]struct{})
    39		for _, v := range numbers {
    40			if _, found := seen[k-v]; found {
    41				return true
    42			}
    43			seen[v] = struct{}{}
    44		}
