// ContiguousSumNonNegative uses a sliding window to return the
// contiguous subset that sums to K. Panics if any element is negative.
// Runtime is O(N) and O(1) space.
func ContiguousSumNonNegative(nums []int, k int) []int {
	for _, n := range nums {
		if n < 0 {
			panic("ContiguousSumNonNegative: negative number not allowed")
		}
	}
	var sum, begin int
	for end := 0; end < len(nums); end++ {
		sum += nums[end]
		for sum > k && begin <= end {
			sum -= nums[begin]
			begin++
		}
		if sum == k {
			return nums[begin : end+1]
		}
	}
	return nil
}

