// contiguous subset that sums to K. Handles negative numbers.
// Runtime is O(N) and O(N) space.
func ContiguousSumNegatives(nums []int, k int) []int {
	prefixSum := make(map[int]int)
	var sum int
	prefixSum[0] = -1
	for i, n := range nums {
		sum += n
		if j, ok := prefixSum[sum-k]; ok {
			return nums[j+1 : i+1]
		}
		prefixSum[sum] = i
	}
	return nil
