    // Actual output:
    println!("{}", alt.to_string()); // prints: ""

    // Expected output:
    // println!("{}", alt.to_string()); // prints: "abc|def"
}
```

A similar example with nested / multiple alternatives:

```rust
let a = Expression::from_literal("abc");
let b = Expression::from_literal("ab");
