impl<'a> fmt::Display for Expression<'a> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Expression::Alternation(exprs, _, _, _) => {
                let mut result = String::new();
                for expr in exprs {
                    result.push_str(&expr.to_string());
                    result.push('|');
                }
                result.pop();
                write!(f, "{}", result)
            }
            Expression::CharacterClass(chars, _) => {
                let mut result = String::new();
                result.push('[');
                for ch in chars {
                    result.push(*ch);
                }
                result.push(']');
                write!(f, "{}", result)
            }
            Expression::Concatenation(expr1, expr2, _, _, _) => {
                write!(f, "{}{}", expr1, expr2)
            }
            Expression::Literal(cluster, _, _) => {
                write!(f, "{}", cluster)
            }
            Expression::Repetition(expr, quantifier, _, _, _) => {
                write!(f, "{}{}", expr, quantifier)
            }
        }
    }
}
